import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
import { emit } from "@/lib/event-bus";
import * as svc from "@/server/services/notification-service";
import * as issueService from "@/server/services/issue-service";
import { buildDigest } from "@/server/services/digest-service";
import { NotFoundError } from "@/server/services/_support";
import { TenantScopeError } from "@/lib/tenant";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { CommentId, ProjectId } from "@/types/common";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("mutes", async () => {
  const t = await createTenant("mute", "growth");
  const o = await createTenant("mute-o", "growth");
  await expect(svc.muteProject(t.actors.admin, o.org.id, t.project.id)).rejects.toBeInstanceOf(TenantScopeError);
  await expect(svc.muteProject(t.actors.admin, t.org.id, "nope" as ProjectId)).rejects.toBeInstanceOf(NotFoundError);
  const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "x" }));
  const before = await svc.notify(t.org.id, "comment_created", [t.userIds.admin], { title: "a", body: "b", href: "/", actorId: null, projectId: t.project.id });
  expect(before).toHaveLength(1);
  await svc.muteProject(t.actors.admin, t.org.id, t.project.id);
  await svc.muteProject(t.actors.admin, t.org.id, t.project.id);
  expect(await svc.listMutedProjectIds(t.actors.admin, t.org.id)).toEqual([t.project.id]);
  expect(await svc.notify(t.org.id, "comment_created", [t.userIds.admin], { title: "a", body: "b", href: "/", actorId: null, projectId: t.project.id })).toHaveLength(0);
  const m = await svc.notify(t.org.id, "comment_mention", [t.userIds.admin], { title: "a", body: "b", href: "/", actorId: null, projectId: t.project.id });
  expect(m[0]?.channels).toEqual(["in_app"]);
  await emit("comment.created", { orgId: t.org.id, actorId: t.userIds.member, occurredAt: issue.createdAt, commentId: "c1" as CommentId, issueId: issue.id, mentionedUserIds: [t.userIds.admin] });
  const now = new Date(Date.now() + 1000).toISOString() as never;
  const start = new Date(Date.now() - 3600_000).toISOString() as never;
  expect(await buildDigest(t.org.id, t.userIds.admin, start, now)).toBeNull();
  await svc.unmuteProject(t.actors.admin, t.org.id, t.project.id);
  await svc.unmuteProject(t.actors.admin, t.org.id, t.project.id);
  expect(await svc.listMutedProjectIds(t.actors.admin, t.org.id)).toEqual([]);
  const d = await buildDigest(t.org.id, t.userIds.admin, start, now);
  console.log(d?.entries.map((e) => e.kind));
});
EOF
